    68→    /**
    69→     * 음절을 조합하여 사전에서 찾아준다. 찾은 단어와 tag는 table에 저장한다.
    70→     */
    71→    private fun doSegment(): ExtractedEntry? {
    72→        val cv = CharVector(source, offset, length)
    73→        // 길이가 1~2 단어는 완전매칭이 아니면 UNK이다.
    74→        if (length == 1) {
    75→            val tag = koreanDict?.find(cv)
    76→            if (tag != null) {
    77→                return ExtractedEntry(length - 1, length, tag[0], offset)
    78→            }
    79→            return when {
    80→                isDigit(cv) -> ExtractedEntry(length - 1, length, TagProb.DIGIT, offset)
    81→                isSymbol(cv) -> ExtractedEntry(length - 1, length, TagProb.SYMBOL, offset)
    82→                else -> ExtractedEntry(length - 1, length, TagProb.UNK, offset)
    83→            }
    84→        }
    85→        val tag = koreanDict?.find(cv)
    86→        if (tag != null) {
    87→            return ExtractedEntry(length - 1, length, tag[0], offset)
    88→        }
    89→        val start = length - 1
    90→        for (row in start downTo 0) {
    91→            for (column in (row + 1) downTo 1) {
    92→                cv.init(offset + row - column + 1, column)
    93→                var isAlpha = false
    94→                when {
    95→                    isDigit(cv) -> {
    96→                        tabular[row][column] = PosTagProbEntry(TagProb.DIGIT)
    97→                        status[row]++
    98→                    }
    99→                    isSymbol(cv) -> {
   100→                        tabular[row][column] = PosTagProbEntry(TagProb.SYMBOL)
   101→                        status[row]++
   102→                    }
   103→                    else -> {
   104→                        if (isAlpha(cv)) {
   105→                            if (column == 1) {
   106→                                tabular[row][column] = PosTagProbEntry(TagProb.ALPHA)
   107→                                continue
   108→                            }
   109→                            isAlpha = true
   110→                        }
   111→                        val tagList = koreanDict?.find(cv)
   112→                        if (tagList != null) {
   113→                            if (column == length) {
   114→                                return ExtractedEntry(row, column, tagList[0], offset)
   115→                            }
   116→                            var chainedEntry: PosTagProbEntry? = null
   117→                            for (i in tagList.indices) {
   118→                                val tagProb = tagList[i]
   119→                                if (i == 0) {
   120→                                    chainedEntry = PosTagProbEntry(tagProb)
   121→                                    tabular[row][column] = chainedEntry
   122→                                } else {
   123→                                    chainedEntry = chainedEntry?.next(tagProb)
   124→                                }
   125→                            }
   126→                            status[row]++
   127→                        } else {
   128→                            tabular[row][column] = if (isAlpha) PosTagProbEntry(TagProb.ALPHA) else null
   129→                        }
   130→
   131→                        if (column < 3) {
   132→                            if (josaSet.contains(cv)) {
   133→                                val entry = PosTagProbEntry(TagProb.JOSA)
   134→                                if (tabular[row][column] == null) {
   135→                                    tabular[row][column] = entry
   136→                                } else {
   137→                                    entry.next = tabular[row][column]
   138→                                    tabular[row][column] = entry
   139→                                }
   140→                                status[row]++
   141→                            }
   142→                        }
   143→                    }
   144→                }
   145→            }
   146→        }
   147→        return null
   148→    }
