   150→    private fun isUnicode(buffer: CharArray, offset: Int, length: Int): Boolean {
   151→        for (inx in 0 until length) {
   152→            val ch = buffer[offset + inx]
   153→            if (ch.code > 127) {
   154→                return true
   155→            }
   156→        }
   157→        return false
   158→    }
   159→
   160→    private fun isDigit(cv: CharVector): Boolean {
   161→        for (i in 0 until cv.length) {
   162→            val ch = cv[i]
   163→            if (ch !in '0'..'9') {
   164→                return false
   165→            }
   166→        }
   167→        return true
   168→    }
   169→
   170→    private fun isAlpha(cv: CharVector): Boolean {
   171→        for (i in 0 until cv.length) {
   172→            val ch = cv[i]
   173→            if (!((ch in 'a'..'z') || (ch in 'A'..'Z'))) {
   174→                return false
   175→            }
   176→        }
   177→        return true
   178→    }
   179→
   180→    private fun isSymbol(cv: CharVector): Boolean {
   181→        for (i in 0 until cv.length) {
   182→            val chInt = cv[i].code
   183→            if (Character.isLetterOrDigit(chInt)) {
   184→                return false
   185→            }
   186→        }
   187→        return true
   188→    }
