   190→    private fun makeResult() {
   191→        var headRow = -1
   192→        for (row in (length - 1) downTo 0) {
   193→            if (status[row] > 0) {
   194→                headRow = row
   195→                break
   196→            }
   197→        }
   198→
   199→        try {
   200→            if (headRow == -1) {
   201→                addResult(ExtractedEntry(length - 1, length, TagProb.UNK, offset))
   202→                return
   203→            }
   204→            if (headRow < length - 1) {
   205→                val tail = ExtractedEntry(length - 1, length - 1 - headRow, TagProb.UNK, offset)
   206→                connectAllTo(headRow, tail)
   207→            } else {
   208→                connectAllTo(headRow, null)
   209→            }
   210→            var tail: ExtractedEntry?
   211→            while (queue.poll().also { tail = it } != null) {
   212→                val connectRow = tail!!.row() - tail!!.column()
   213→                if (status[connectRow] > 0) {
   214→                    connectAllTo(connectRow, tail)
   215→                } else {
   216→                    connectTo(null, connectRow, -1, tail)
   217→                }
   218→            }
   219→        } catch (e: AnalyzeExceedException) {
   220→            logger.debug("Analyze exceed : " + e.message)
   221→        }
   222→    }
