   360→                type = TokenTypes.getType(buffer[inx - 1].code)
   361→                if (logger.isTraceEnabled) {
   362→                    logger.trace(
   363→                        "PP:{}/P:{}/T:{}/C:{} {} [{}/{}/{} | {}/{}/{}]", pptype, ptype, type, buffer[inx - 1],
   364→                        inx - offset,
   365→                        (pptype != null && (pptype != TokenTypes.ALPHA && pptype != TokenTypes.NUMBER)),
   366→                        (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&'),
   367→                        (type != null), (pptype != null),
   368→                        (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&'),
   369→                        (type != null && (type != TokenTypes.ALPHA && type != TokenTypes.NUMBER))
   370→                    )
   371→                }
   372→                if (((pptype != null && (pptype != TokenTypes.ALPHA && pptype != TokenTypes.NUMBER))
   373→                            && (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&')
   374→                            && (type != null))
   375→                    || ((pptype != null) && (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&')
   376→                            && (type != null && (type != TokenTypes.ALPHA && type != TokenTypes.NUMBER)))
   377→                ) {
   378→                    logger.trace("LENGTH:{} / {}", len - offset, tabular.size)
   379→                    len = inx - offset
   380→                    if (len <= tabular.size) {
   381→                        logger.trace("BREAK INTO {}", len)
