   428→    fun extract(): ExtractedEntry {
   429→        tabularStringer.set(tabular, source, status, length, offset)
   430→        ExtractedEntry.source = source
   431→        var e = extract0()
   432→        var last = e.last()
   433→        while (remnantLength > 0) {
   434→            val len = minOf(tabular.size, remnantLength)
   435→            setInput0(source, remnantOffset, len)
   436→            val r = extract0()
   437→            if (!(last.offset() + last.column() > r.offset())) {
   438→                last.next(r)
   439→                last = r.last()
   440→            }
   441→            remnantOffset += len
   442→            remnantLength -= len
   443→        }
   444→        return e
   445→    }
