   487→    /**
   488→     * 두 PosTag간의 룰기반 접속문법검사
   489→     */
   490→    protected fun isConnectableByRule(headTagProb: TagProb, headRow: Int, headColumn: Int, tail: ExtractedEntry): Boolean {
   491→        if (headTagProb.posTag() == PosTag.DIGIT && tail.tagProb().posTag() == PosTag.DIGIT) {
   492→            return false
   493→        }
   494→        if (headTagProb.posTag() == PosTag.ALPHA && tail.tagProb().posTag() == PosTag.ALPHA) {
   495→            return false
   496→        }
   497→        if (headTagProb.posTag() == PosTag.SYMBOL && tail.tagProb().posTag() == PosTag.SYMBOL) {
   498→            return false
   499→        }
   500→        if (headTagProb.posTag() != PosTag.ALPHA && headTagProb.posTag() != PosTag.DIGIT && headTagProb.posTag() != PosTag.SYMBOL) {
   501→            if (tail.tagProb().posTag() == PosTag.J && tail.column() == 1) {
   502→                val ch = source[offset + tail.row() - tail.column() + 1]
   503→                if (ch == '은' || ch == '이' || ch == '을' || ch == '과') {
   504→                    if (!MorphUtil.hasLastElement(source[offset + headRow])) {
   505→                        return false
   506→                    }
   507→                } else if (ch == '는' || ch == '가' || ch == '를' || ch == '와') {
   508→                    if (MorphUtil.hasLastElement(source[offset + headRow])) {
   509→                        return false
   510→                    }
   511→                }
   512→            }
   513→        }
   514→
   515→        if (headColumn == 1 && tail.column() == 1 && headTagProb.posTag() != PosTag.J && tail.posTag() != PosTag.J) {
   516→            if (tabular[tail.row()][tail.column() + headColumn] != null) {
   517→                return false
   518→            }
   519→        }
   520→        return true
   521→    }
