   523→    /**
   524→     * 두 엔트리를 접속시 합치거나 이어붙이는 로직을 구현한다.
   525→     */
   526→    protected fun modifyAndConnect(tagProb: TagProb, row: Int, column: Int, tail: ExtractedEntry): ExtractedEntry {
   527→        val newEntry = ExtractedEntry(row, column, tagProb, offset)
   528→        return newEntry.next(tail)
   529→    }
