   531→    private fun finalCheck(headEntry: ExtractedEntry): ExtractedEntry? {
   532→        if (headEntry.posTag() == PosTag.J) {
   533→            return null
   534→        }
   535→
   536→        var count = 0
   537→        if (headEntry.entryCount() >= 2) {
   538→            var current: ExtractedEntry? = headEntry
   539→            while (current != null) {
   540→                if (current.column() > 1) {
   541→                    break
   542→                } else {
   543→                    count++
   544→                }
   545→                current = current.next()
   546→            }
   547→        }
   548→
   549→        if (count == headEntry.entryCount()) {
   550→            if (headEntry.last().posTag() == PosTag.J) {
   551→                return headEntry
   552→            }
   553→            return null
   554→        }
   555→        return headEntry
   556→    }
