package com.danawa.search.analysis.korean

import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.search.analysis.korean.PosTagProbEntry.PosTag
import com.danawa.search.analysis.korean.PosTagProbEntry.TagProb
import com.danawa.search.analysis.product.AnalyzeExceedException
import com.danawa.search.analysis.product.TokenTypes
import com.danawa.util.CharVector

import org.elasticsearch.common.logging.Loggers
import java.util.PriorityQueue

/**
 * Korean word extractor using CYK-style dynamic programming.
 * Extracts morphemes from Korean text using a probability-based scoring system.
 */
class KoreanWordExtractor @JvmOverloads constructor(
    private var koreanDict: ProductNameDictionary?,
    tabularSize: Int = 20
) {
    private val tabular: Array<Array<PosTagProbEntry?>>
    private val status: IntArray
    private val josaSet: MutableSet<CharVector>

    // 최상의 후보가 만들어지면 바로 리턴. 기본 true
    var fastResultOption: Boolean = true
    // 발견되었는지 여부
    private var fastResultFound: Boolean = false
    private var remnantOffset: Int = 0
    private var remnantLength: Int = 0
    private var isUnicode: Boolean = false
    private val charVector = CharVector()
    private val tabularStringer: TabularStringer
    private val entryStringer: EntryStringer

    private val queue = PriorityQueue<ExtractedEntry>(8) { o1, o2 ->
        (o2.totalScore() - o1.totalScore()).toInt()
    }

    private val result: MutableList<ExtractedEntry> = mutableListOf()

    protected var source: CharArray = CharArray(0)
    protected var offset: Int = 0
    protected var length: Int = 0

    init {
        tabular = Array(tabularSize) { row ->
            arrayOfNulls(row + 2)
        }
        status = IntArray(tabularSize)
        josaSet = mutableSetOf()
        val josaList = "은 는 이 가 을 를 에 과 와 의 로 만 께 에게 에서 으로 부터 라서 라고 께서 한테 처럼 같이 라는 하며 하고 까지 이라고 이라는 이라도 이라면 에서도 이기도"
        for (j in josaList.split("\\s".toRegex())) {
            josaSet.add(CharVector(j))
        }
        tabularStringer = TabularStringer()
        entryStringer = EntryStringer()
    }

    fun dictionary(): ProductNameDictionary? = koreanDict

    fun setKoreanDic(koreanDict: ProductNameDictionary?) {
        this.koreanDict = koreanDict
    }

    // Property setter is generated automatically by Kotlin for 'var fastResultOption'

    /**
     * 음절을 조합하여 사전에서 찾아준다. 찾은 단어와 tag는 table에 저장한다.
     */
    private fun doSegment(): ExtractedEntry? {
        val cv = CharVector(source, offset, length)
        // 길이가 1~2 단어는 완전매칭이 아니면 UNK이다.
        if (length == 1) {
            val tag = koreanDict?.find(cv)
            if (tag != null) {
                return ExtractedEntry(length - 1, length, tag[0], offset)
            }
            return when {
                isDigit(cv) -> ExtractedEntry(length - 1, length, TagProb.DIGIT, offset)
                isSymbol(cv) -> ExtractedEntry(length - 1, length, TagProb.SYMBOL, offset)
                else -> ExtractedEntry(length - 1, length, TagProb.UNK, offset)
            }
        }
        val tag = koreanDict?.find(cv)
        if (tag != null) {
            return ExtractedEntry(length - 1, length, tag[0], offset)
        }
        val start = length - 1
        for (row in start downTo 0) {
            for (column in (row + 1) downTo 1) {
                cv.init(offset + row - column + 1, column)
                var isAlpha = false
                when {
                    isDigit(cv) -> {
                        tabular[row][column] = PosTagProbEntry(TagProb.DIGIT)
                        status[row]++
                    }
                    isSymbol(cv) -> {
                        tabular[row][column] = PosTagProbEntry(TagProb.SYMBOL)
                        status[row]++
                    }
                    else -> {
                        if (isAlpha(cv)) {
                            if (column == 1) {
                                tabular[row][column] = PosTagProbEntry(TagProb.ALPHA)
                                continue
                            }
                            isAlpha = true
                        }
                        val tagList = koreanDict?.find(cv)
                        if (tagList != null) {
                            if (column == length) {
                                return ExtractedEntry(row, column, tagList[0], offset)
                            }
                            var chainedEntry: PosTagProbEntry? = null
                            for (i in tagList.indices) {
                                val tagProb = tagList[i]
                                if (i == 0) {
                                    chainedEntry = PosTagProbEntry(tagProb)
                                    tabular[row][column] = chainedEntry
                                } else {
                                    chainedEntry = chainedEntry?.next(tagProb)
                                }
                            }
                            status[row]++
                        } else {
                            tabular[row][column] = if (isAlpha) PosTagProbEntry(TagProb.ALPHA) else null
                        }

                        if (column < 3) {
                            if (josaSet.contains(cv)) {
                                val entry = PosTagProbEntry(TagProb.JOSA)
                                if (tabular[row][column] == null) {
                                    tabular[row][column] = entry
                                } else {
                                    entry.next = tabular[row][column]
                                    tabular[row][column] = entry
                                }
                                status[row]++
                            }
                        }
                    }
                }
            }
        }
        return null
    }

    private fun isUnicode(buffer: CharArray, offset: Int, length: Int): Boolean {
        for (inx in 0 until length) {
            val ch = buffer[offset + inx]
            if (ch.code > 127) {
                return true
            }
        }
        return false
    }

    private fun isDigit(cv: CharVector): Boolean {
        for (i in 0 until cv.length) {
            val ch = cv[i]
            if (ch !in '0'..'9') {
                return false
            }
        }
        return true
    }

    private fun isAlpha(cv: CharVector): Boolean {
        for (i in 0 until cv.length) {
            val ch = cv[i]
            if (!((ch in 'a'..'z') || (ch in 'A'..'Z'))) {
                return false
            }
        }
        return true
    }

    private fun isSymbol(cv: CharVector): Boolean {
        for (i in 0 until cv.length) {
            val chInt = cv[i].code
            if (Character.isLetterOrDigit(chInt)) {
                return false
            }
        }
        return true
    }

    private fun makeResult() {
        var headRow = -1
        for (row in (length - 1) downTo 0) {
            if (status[row] > 0) {
                headRow = row
                break
            }
        }

        try {
            if (headRow == -1) {
                addResult(ExtractedEntry(length - 1, length, TagProb.UNK, offset))
                return
            }
            if (headRow < length - 1) {
                val tail = ExtractedEntry(length - 1, length - 1 - headRow, TagProb.UNK, offset)
                connectAllTo(headRow, tail)
            } else {
                connectAllTo(headRow, null)
            }
            var tail: ExtractedEntry?
            while (queue.poll().also { tail = it } != null) {
                val connectRow = tail!!.row() - tail!!.column()
                if (status[connectRow] > 0) {
                    connectAllTo(connectRow, tail)
                } else {
                    connectTo(null, connectRow, -1, tail)
                }
            }
        } catch (e: AnalyzeExceedException) {
            logger.debug("Analyze exceed : " + e.message)
        }
    }

    @Throws(AnalyzeExceedException::class)
    private fun connectAllTo(headRow: Int, tail: ExtractedEntry?): Int {
        val rowData = tabular[headRow]
        var found = 0
        for (headColumn in (headRow + 1) downTo 1) {
            if (rowData[headColumn] != null) {
                val tagEntry = rowData[headColumn]!!
                entryStringer.set(tagEntry, source, headRow, headColumn, offset)
                if (tagEntry.tagProb?.posTag() != PosTag.ALPHA) {
                    connectTo(tagEntry, headRow, headColumn, tail)
                    found++
                }
            }
            if (found >= status[headRow]) {
                break
            }
        }
        if (!isUnicode) {
            val iter = result.iterator()
            while (iter.hasNext()) {
                val entry = iter.next()
                if (entry.last().posTag() == PosTag.UNK) {
                    iter.remove()
                }
            }
        }
        return found
    }

    @Throws(AnalyzeExceedException::class)
    private fun connectTo(
        headTagEntry: PosTagProbEntry?,
        headRow: Int,
        headColumn: Int,
        tail: ExtractedEntry?
    ): Int {
        var currentEntry = headTagEntry
        if (tail == null) {
            var found = 0
            while (currentEntry != null) {
                val headEntry = ExtractedEntry(headRow, headColumn, currentEntry.get()!!, offset)
                if (headEntry.row() - headEntry.column() < 0) {
                    addResult(headEntry)
                } else {
                    addQueue(headEntry)
                }
                currentEntry = currentEntry.next
                found++
            }
            return found
        }

        if (currentEntry == null) {
            for (column in 1..(headRow + 1)) {
                val row2 = headRow - column
                if (row2 < 0 || status[row2] > 0) {
                    // 2014-1-27처리..
                }
            }
            return 1
        }

        var found = 0
        while (currentEntry != null) {
            if (isConnectableByRule(currentEntry.get()!!, headRow, headColumn, tail)) {
                val newTail = modifyAndConnect(currentEntry.get()!!, headRow, headColumn, tail)
                if (newTail != null) {
                    if (newTail.row() - newTail.column() < 0) {
                        addResult(newTail)
                    } else {
                        addQueue(newTail)
                    }
                    found++
                }
            }
            currentEntry = currentEntry.next
        }
        return found
    }

    @Throws(AnalyzeExceedException::class)
    protected fun addQueue(entry: ExtractedEntry) {
        if (fastResultFound) {
            return
        }
        queue.add(entry)
        if (queue.size >= QUEUE_MAX) {
            throw AnalyzeExceedException("Queue size exceed ${queue.size} : ${String(source)}")
        }
    }

    @Throws(AnalyzeExceedException::class)
    protected fun addResult(entry: ExtractedEntry) {
        val e = finalCheck(entry) ?: return
        result.add(entry)

        if (fastResultOption && length > 6) {
            fastResultFound = true
            queue.clear()
        }

        if (result.size >= RESULT_MAX) {
            val tmpResult = getHighResult()
            result.clear()
            if (tmpResult != null) {
                result.add(tmpResult)
            }
        }
    }

    fun setInput(buffer: CharArray, length: Int): Int {
        return setInput(buffer, 0, length)
    }

    fun setInput(buffer: CharArray, offset: Int, length: Int): Int {
        var len = length
        remnantOffset = 0
        remnantLength = 0
        isUnicode = isUnicode(buffer, offset, len)
        status.fill(0)
        for (row in tabular.indices) {
            for (col in tabular[row].indices) {
                tabular[row][col] = null
            }
        }
        result.clear()

        var type: String? = null
        var ptype: String? = null
        var pptype: String?

        if (len > tabular.size) {
            logger.trace("LENGTH IS OVER THAN {} / {} / {}", len, tabular.size, offset)
            for (inx in (offset + len) downTo (offset + 1)) {
                pptype = ptype
                ptype = type
                type = TokenTypes.getType(buffer[inx - 1].code)
                if (logger.isTraceEnabled) {
                    logger.trace(
                        "PP:{}/P:{}/T:{}/C:{} {} [{}/{}/{} | {}/{}/{}]", pptype, ptype, type, buffer[inx - 1],
                        inx - offset,
                        (pptype != null && (pptype != TokenTypes.ALPHA && pptype != TokenTypes.NUMBER)),
                        (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&'),
                        (type != null), (pptype != null),
                        (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&'),
                        (type != null && (type != TokenTypes.ALPHA && type != TokenTypes.NUMBER))
                    )
                }
                if (((pptype != null && (pptype != TokenTypes.ALPHA && pptype != TokenTypes.NUMBER))
                            && (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&')
                            && (type != null))
                    || ((pptype != null) && (inx < buffer.size && ptype == TokenTypes.SYMBOL && buffer[inx] != '&')
                            && (type != null && (type != TokenTypes.ALPHA && type != TokenTypes.NUMBER)))
                ) {
                    logger.trace("LENGTH:{} / {}", len - offset, tabular.size)
                    len = inx - offset
                    if (len <= tabular.size) {
                        logger.trace("BREAK INTO {}", len)
                        break
                    }
                }
            }
            if (len > tabular.size) {
                type = null
                for (inx in offset until (offset + len)) {
                    ptype = type
                    type = TokenTypes.getType(buffer[inx].code)
                    if (ptype != null && (
                                ((type == TokenTypes.ALPHA || type == TokenTypes.NUMBER || type == TokenTypes.SYMBOL)
                                        && !(ptype == TokenTypes.ALPHA || ptype == TokenTypes.NUMBER || ptype == TokenTypes.SYMBOL))
                                        || (!(type == TokenTypes.ALPHA || type == TokenTypes.NUMBER || type == TokenTypes.SYMBOL)
                                        && (ptype == TokenTypes.ALPHA || ptype == TokenTypes.NUMBER || ptype == TokenTypes.SYMBOL))
                                )
                    ) {
                        len = inx - offset
                    }
                }
            }

            if (len > tabular.size) {
                if (logger.isTraceEnabled) {
                    logger.trace(
                        "CUT TABULAR SIZE : {}/ {} -> {}", len, String(buffer, offset, len),
                        String(buffer, offset, tabular.size)
                    )
                }
                remnantOffset = tabular.size
                remnantLength = len - tabular.size
                len = tabular.size
            }
        }
        return setInput0(buffer, offset, len)
    }

    private fun setInput0(buffer: CharArray, offset: Int, length: Int): Int {
        this.source = buffer
        queue.clear()
        result.clear()
        this.offset = offset
        this.length = length
        fastResultFound = false
        return length
    }

    fun extract(): ExtractedEntry {
        tabularStringer.set(tabular, source, status, length, offset)
        ExtractedEntry.source = source
        var e = extract0()
        var last = e.last()
        while (remnantLength > 0) {
            val len = minOf(tabular.size, remnantLength)
            setInput0(source, remnantOffset, len)
            val r = extract0()
            if (!(last.offset() + last.column() > r.offset())) {
                last.next(r)
                last = r.last()
            }
            remnantOffset += len
            remnantLength -= len
        }
        return e
    }

    fun extract0(): ExtractedEntry {
        val e = doSegment()
        if (e != null) {
            return e
        }
        makeResult()
        return getBestResult()
    }

    fun getAllResult(): List<ExtractedEntry> = result

    private fun getHighResult(): ExtractedEntry? {
        var highEntry: ExtractedEntry? = null
        for (k in result.indices) {
            var entry: ExtractedEntry? = result[k]
            entry = finalCheck(entry!!) ?: continue
            charVector.init(source, entry.offset(), entry.column())

            if (highEntry == null) {
                highEntry = entry
            } else {
                if (isBetterThan(entry, highEntry)) {
                    highEntry = entry
                }
            }
        }
        return highEntry
    }

    fun getBestResult(): ExtractedEntry {
        var bestEntry = getHighResult()
        if (bestEntry == null) {
            bestEntry = ExtractedEntry(length - 1, length, TagProb.UNK, offset)
            return bestEntry
        }
        return bestEntry
    }

    fun getTabularSize(): Int = tabular.size

    /**
     * 두 PosTag간의 룰기반 접속문법검사
     */
    protected fun isConnectableByRule(headTagProb: TagProb, headRow: Int, headColumn: Int, tail: ExtractedEntry): Boolean {
        if (headTagProb.posTag() == PosTag.DIGIT && tail.tagProb().posTag() == PosTag.DIGIT) {
            return false
        }
        if (headTagProb.posTag() == PosTag.ALPHA && tail.tagProb().posTag() == PosTag.ALPHA) {
            return false
        }
        if (headTagProb.posTag() == PosTag.SYMBOL && tail.tagProb().posTag() == PosTag.SYMBOL) {
            return false
        }
        if (headTagProb.posTag() != PosTag.ALPHA && headTagProb.posTag() != PosTag.DIGIT && headTagProb.posTag() != PosTag.SYMBOL) {
            if (tail.tagProb().posTag() == PosTag.J && tail.column() == 1) {
                val ch = source[offset + tail.row() - tail.column() + 1]
                if (ch == '은' || ch == '이' || ch == '을' || ch == '과') {
                    if (!MorphUtil.hasLastElement(source[offset + headRow])) {
                        return false
                    }
                } else if (ch == '는' || ch == '가' || ch == '를' || ch == '와') {
                    if (MorphUtil.hasLastElement(source[offset + headRow])) {
                        return false
                    }
                }
            }
        }

        if (headColumn == 1 && tail.column() == 1 && headTagProb.posTag() != PosTag.J && tail.posTag() != PosTag.J) {
            if (tabular[tail.row()][tail.column() + headColumn] != null) {
                return false
            }
        }
        return true
    }

    /**
     * 두 엔트리를 접속시 합치거나 이어붙이는 로직을 구현한다.
     */
    protected fun modifyAndConnect(tagProb: TagProb, row: Int, column: Int, tail: ExtractedEntry): ExtractedEntry {
        val newEntry = ExtractedEntry(row, column, tagProb, offset)
        return newEntry.next(tail)
    }

    private fun finalCheck(headEntry: ExtractedEntry): ExtractedEntry? {
        if (headEntry.posTag() == PosTag.J) {
            return null
        }

        var count = 0
        if (headEntry.entryCount() >= 2) {
            var current: ExtractedEntry? = headEntry
            while (current != null) {
                if (current.column() > 1) {
                    break
                } else {
                    count++
                }
                current = current.next()
            }
        }

        if (count == headEntry.entryCount()) {
            if (headEntry.last().posTag() == PosTag.J) {
                return headEntry
            }
            return null
        }
        return headEntry
    }

    /**
     * Best 결과를 뽑을때 사용하는 비교로직.
     */
    protected fun isBetterThan(entry: ExtractedEntry, bestEntry: ExtractedEntry): Boolean {
        if (entry.totalScore() > bestEntry.totalScore()) {
            return true
        }
        return false
    }

    /**
     * Extracted entry representing a morpheme analysis result.
     */
    class ExtractedEntry : Cloneable {
        private var row: Int
        private var column: Int
        private var tagProb: TagProb
        private var next: ExtractedEntry? = null
        private var score: Double = 0.0
        private var extracted: Boolean = false
        private var _offset: Int

        constructor(row: Int, column: Int, tagProb: TagProb) : this(row, column, tagProb, 0.0)

        constructor(row: Int, column: Int, tagProb: TagProb, scoreAdd: Double) {
            this.row = row
            this.column = column
            this.tagProb = tagProb
            this._offset = 0
            this.score += (tagProb.prob() + scoreAdd)
        }

        constructor(row: Int, column: Int, tagProb: TagProb, offset: Int) {
            this.row = row
            this.column = column
            this.tagProb = tagProb
            this._offset = offset
            this.score += tagProb.prob()
        }

        fun tagProb(): TagProb = tagProb

        fun posTag(): PosTag = tagProb.posTag()

        fun tagProb(tagProb: TagProb) {
            this.score -= this.tagProb.prob()
            this.tagProb = tagProb
            this.score += tagProb.prob()
        }

        fun offset(): Int = _offset + row - column + 1

        fun row(): Int = row

        fun row(row: Int) {
            this.row = row
        }

        fun column(): Int = column

        fun column(column: Int) {
            this.column = column
        }

        fun addScore(score: Int) {
            this.score += score
        }

        fun totalScore(): Double = score

        fun entryCount(): Int {
            var nextEntry: ExtractedEntry? = this
            var count = 0
            while (nextEntry != null) {
                count++
                nextEntry = nextEntry.next
            }
            return count
        }

        fun charSize(): Int = column

        fun next(): ExtractedEntry? = next

        fun last(): ExtractedEntry {
            var l: ExtractedEntry = this
            while (true) {
                if (l.next() == null) {
                    return l
                } else {
                    l = l.next()!!
                }
            }
        }

        fun setNext(next: ExtractedEntry?) {
            this.next = next
        }

        fun next(next: ExtractedEntry?): ExtractedEntry {
            this.next = next
            if (next != null) {
                this.score += next.score
            }
            return this
        }

        fun isExtracted(): Boolean = extracted

        fun setExtracted(extracted: Boolean) {
            this.extracted = extracted
        }

        fun getChainedString(): String {
            return if (next == null) {
                toString()
            } else {
                toString() + " + " + next!!.getChainedString()
            }
        }

        fun getChainedShortString(source: CharArray): String {
            return if (next == null) {
                toShortString(source)
            } else {
                toShortString(source) + " + " + next!!.getChainedShortString(source)
            }
        }

        fun getChainedString(source: CharArray): String {
            return if (next == null) {
                toDetailString(source)
            } else {
                toDetailString(source) + " + " + next!!.getChainedString(source)
            }
        }

        public override fun clone(): ExtractedEntry {
            return try {
                super.clone() as ExtractedEntry
            } catch (e: CloneNotSupportedException) {
                logger.error("", e)
                this
            }
        }

        override fun toString(): String {
            return "(${String(source, row + _offset - column + 1, column)}:${row + _offset},$column):$tagProb:$score"
        }

        fun toWord(source: CharArray): String {
            return String(source, row + _offset - column + 1, column)
        }

        fun toShortString(source: CharArray): String {
            return String(source, row + _offset - column + 1, column) + ":" + tagProb.toShortString()
        }

        fun toDetailString(source: CharArray): String {
            return try {
                String(source, row + _offset - column + 1, column) + "(" + (row + _offset) + "," + column + "):" + tagProb + ":" + score
            } catch (e: Exception) {
                logger.debug("{} ({},{})", String(source), row + _offset - column + 1, column)
                throw RuntimeException()
            }
        }

        companion object {
            @JvmField
            var source: CharArray = CharArray(0)
        }
    }

    class EntryStringer {
        private var entry: PosTagProbEntry? = null
        private var row: Int = 0
        private var column: Int = 0

        fun set(entry: PosTagProbEntry, source: CharArray, row: Int, column: Int, offset: Int) {
            this.entry = entry
            this.row = row
            this.column = column
            Companion.source = source
            Companion.offset = offset
        }

        override fun toString(): String {
            val sb = StringBuilder()
            sb.append(String(source, row - column + 1 + offset, column)).append("[")
            var e = entry
            while (e != null) {
                sb.append(e.get())
                e = e.next()
            }
            sb.append("]")
            return sb.toString()
        }

        companion object {
            private var source: CharArray = CharArray(0)
            private var offset: Int = 0
        }
    }

    class TabularStringer {
        fun set(tabular: Array<Array<PosTagProbEntry?>>, source: CharArray, status: IntArray, length: Int, offset: Int) {
            Companion.tabular = tabular
            Companion.source = source
            Companion.status = status
            Companion.length = length
            Companion.offset = offset
        }

        override fun toString(): String {
            val ret = StringBuilder()
            for (row in 0 until length) {
                val el = tabular[row]
                val count = status[row]
                val sb = StringBuilder()
                sb.append("").append(row).append(" ")
                    .append("{ ").append(count).append(" }").append(" | ")
                for (column in 1..(row + 1)) {
                    var e = el[column]
                    sb.append(String(source, row - column + 1 + offset, column)).append("[")
                    while (e != null) {
                        sb.append(e.get())
                        e = e.next()
                    }
                    sb.append("]").append(" | ")
                }
                ret.append("\r\n").append(sb)
            }
            return ret.toString()
        }

        companion object {
            private var source: CharArray = CharArray(0)
            private var tabular: Array<Array<PosTagProbEntry?>> = emptyArray()
            private var status: IntArray = IntArray(0)
            private var length: Int = 0
            private var offset: Int = 0
        }
    }

    companion object {
        private val logger = Loggers.getLogger(KoreanWordExtractor::class.java, "")
        private const val QUEUE_MAX = 200
        private const val RESULT_MAX = 10
    }
}

package com.danawa.search.analysis.korean

import java.io.Serializable

/**
 * POS tag with probability entry for Korean morphological analysis
 */
class PosTagProbEntry : Serializable {
    @JvmField
    var tagProb: TagProb? = null

    @JvmField
    var next: PosTagProbEntry? = null

    @JvmField
    var key: CharSequence? = null

    constructor()

    constructor(tagProb: TagProb?) {
        this.tagProb = tagProb
    }

    constructor(tagProb: TagProb?, cvKey: CharSequence?) {
        this.tagProb = tagProb
        this.key = cvKey
    }

    fun set(tagProb: TagProb?) {
        this.tagProb = tagProb
    }

    fun get(): TagProb? = tagProb

    fun next(next: TagProb?): PosTagProbEntry {
        val newEntry = PosTagProbEntry(next)
        newEntry.key = this.key
        this.next = newEntry
        return newEntry
    }

    fun next(): PosTagProbEntry? = next

    fun contains(posTag: TagProb?): Boolean {
        var nextTagEntry: PosTagProbEntry? = this
        while (nextTagEntry != null) {
            if (nextTagEntry.get() === posTag) {
                return true
            }
            nextTagEntry = nextTagEntry.next()
        }
        return false
    }

    fun posContains(posTag: PosTag): Boolean {
        var nextTagEntry: PosTagProbEntry? = this
        while (nextTagEntry != null) {
            if (nextTagEntry.get()?.posTag == posTag) {
                return true
            }
            nextTagEntry = nextTagEntry.next()
        }
        return false
    }

    enum class PosTag {
        SOE, UNK, N, V, M, IC, J, E, EP, X, ALPHA /* 영문 */, XPN, EOE, GUESS, DIGIT, SYMBOL
    }

    class TagProb : Serializable {
        @JvmField
        val posTag: PosTag

        private val prob: Double

        @JvmOverloads
        constructor(posTag: PosTag, prob: Double = MIN_PROB) {
            this.posTag = posTag
            this.prob = prob
        }

        fun posTag(): PosTag = posTag

        fun prob(): Double = prob

        override fun equals(other: Any?): Boolean {
            if (other !is TagProb) return false
            // 태그만 같다면 같은것으로 본다.
            return other.posTag == this.posTag
        }

        override fun hashCode(): Int = posTag.hashCode()

        override fun toString(): String = "${posTag.name}[$prob]"

        fun toShortString(): String = posTag.name

        companion object {
            private const val serialVersionUID = 1L

            const val MAX_PROB = -5.0
            const val HIGH_PROB = -8.0
            const val P11_PROB = -11.0
            const val P12_PROB = -12.0
            const val MID_PROB = -13.0
            const val LOW_PROB = -14.0
            const val MIN_PROB = -16.0

            @JvmField
            val UNK = TagProb(PosTag.UNK)

            @JvmField
            val GUESS = TagProb(PosTag.GUESS)

            @JvmField
            val DIGIT = TagProb(PosTag.DIGIT, HIGH_PROB)

            @JvmField
            val ALPHA = TagProb(PosTag.ALPHA, HIGH_PROB)

            @JvmField
            val SYMBOL = TagProb(PosTag.SYMBOL)

            @JvmField
            val JOSA = TagProb(PosTag.J, MID_PROB)

            @JvmStatic
            fun getProb(probType: String?): Double {
                if (probType.isNullOrEmpty()) {
                    return -1.0
                }
                return when (probType.lowercase()) {
                    "max" -> MAX_PROB
                    "high" -> HIGH_PROB
                    "mid" -> MID_PROB
                    "p11" -> P11_PROB
                    "p12" -> P12_PROB
                    "low" -> LOW_PROB
                    "min" -> MIN_PROB
                    else -> MIN_PROB
                }
            }
        }
    }

    companion object {
        private const val serialVersionUID = 1L
    }
}

